import{_ as e,o as a,c as o,a3 as i}from"./chunks/framework.DAK02U1-.js";const p=JSON.parse('{"title":"Compatibility","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Compatibility | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/xclang/reference/compatibility"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/xclang/reference/compatibility"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/reference/compatibility"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/reference/compatibility"}]]},"headers":[],"relativePath":"xclang/reference/compatibility.md","filePath":"en/xclang/reference/compatibility.md","lastUpdated":1791301679000}'),r={name:"xclang/reference/compatibility.md"};function d(n,t,l,s,c,h){return a(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="compatibility" tabindex="-1">Compatibility <a class="header-anchor" href="#compatibility" aria-label="Permalink to &quot;Compatibility&quot;">​</a></h1><p>The oldest systems and tools that xclang, and the programs it builds, work with.</p><h2 id="the-toolchain" tabindex="-1">The Toolchain <a class="header-anchor" href="#the-toolchain" aria-label="Permalink to &quot;The Toolchain&quot;">​</a></h2><table tabindex="0"><thead><tr><th>host</th><th>needs</th></tr></thead><tbody><tr><td>Linux x64, arm64</td><td>glibc 2.17 or later; nothing else (clang and lld link libc++ statically)</td></tr><tr><td>macOS arm64, x64</td><td>macOS 13 or later; for macOS targets, Xcode or the Command Line Tools (the SDK)</td></tr><tr><td>Windows x64, arm64</td><td>Windows 10 or later (UCRT is part of the OS)</td></tr></tbody></table><h2 id="programs-it-builds" tabindex="-1">Programs It Builds <a class="header-anchor" href="#programs-it-builds" aria-label="Permalink to &quot;Programs It Builds&quot;">​</a></h2><table tabindex="0"><thead><tr><th>target</th><th>runs on</th></tr></thead><tbody><tr><td>Linux x64, arm64</td><td>glibc 2.17 or later: CentOS 7, Debian 8, Ubuntu 14.04 and every later distribution with glibc</td></tr><tr><td>Windows x64, arm64</td><td>Windows 10 or later, where UCRT is part of the OS</td></tr><tr><td>macOS arm64, x64</td><td>macOS 13.0 or later; a <code>-mmacos-version-min</code> on the command line comes after the config file&#39;s 13.0 and replaces it</td></tr></tbody></table><p>What a program loads at run time is in <a href="./../design/hermeticity">hermeticity</a>.</p><h2 id="build-tools" tabindex="-1">Build Tools <a class="header-anchor" href="#build-tools" aria-label="Permalink to &quot;Build Tools&quot;">​</a></h2><table tabindex="0"><thead><tr><th>tool</th><th>version</th><th>why</th></tr></thead><tbody><tr><td>CMake</td><td>3.28 or later</td><td>the first that builds C++20 modules without experimental switches; <code>find_package(xclang)</code> refuses older ones</td></tr><tr><td>Ninja</td><td>1.11 or later</td><td>what CMake requires to build C++20 modules; only the Ninja generators build them for these targets</td></tr><tr><td>Bazel</td><td>9, with rules_cc 0.2.25</td><td>the toolchains are rules_cc 0.2.25&#39;s; C++20 modules need <code>--experimental_cpp_modules</code></td></tr><tr><td>Xcode</td><td>any whose SDK ld64.lld reads; Xcode 27 needs 23.1.2.6 or later</td><td>the macOS 27 SDK lists <code>arm64e.x1</code>, which ld64.lld reads with <a href="./patches">patch 0009</a></td></tr><tr><td>Rust</td><td>the <code>*-windows-gnullvm</code> targets for Windows, not <code>*-windows-gnu</code></td><td>their std links libunwind and UCRT, as the MinGW sysroots have them (<a href="./../integrations/cargo">Rust and Cargo</a>)</td></tr></tbody></table><p>Since 23.1.2.7, clang and clang-cl build for <code>*-pc-windows-msvc</code> against the SDK the <code>xclang</code> command fetches, not an installed Visual Studio (<a href="./../integrations/clang#msvc-targets">MSVC targets</a>); lld-link, which reads no config file, finds its libraries where they say, or by <code>/winsysroot</code>. <code>--no-default-config</code> looks for Visual Studio, as upstream clang does and releases before 23.1.2.7 did.</p><h2 id="not-yet-supported" tabindex="-1">Not Yet Supported <a class="header-anchor" href="#not-yet-supported" aria-label="Permalink to &quot;Not Yet Supported&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>status</th></tr></thead><tbody><tr><td><a href="./../design/roadmap#msan">MemorySanitizer</a></td><td><span class="status-badge note">Planned</span></td></tr><tr><td><a href="./../design/roadmap#mingw-sanitizers">Sanitizers for MinGW targets</a></td><td><span class="status-badge note">Considered</span></td></tr></tbody></table><h2 id="known-limitations" tabindex="-1">Known Limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known Limitations&quot;">​</a></h2><ul><li><strong>Linux, from glibc 2.17</strong>: no <code>-static-pie</code>, as glibc 2.17 has no <code>rcrt1.o</code>. <code>-pg</code> needs <code>-no-pie</code>, as its <code>gcrt1.o</code> is not position-independent. No <code>quadmath.h</code>: <code>libquadmath</code> is GCC&#39;s own, and <code>__float128</code> arithmetic works.</li><li><strong>One libc++ per shared object</strong>: a standard exception thrown by one shared library is caught by type in another only on Windows; on Linux and macOS only as <code>catch (...)</code>. See <a href="./../design/hermeticity#one-libc-per-shared-object">hermeticity</a>.</li><li><strong>No OpenMP runtime</strong> (<code>-fopenmp</code>); one is <a href="./../design/roadmap#openmp">not planned</a>.</li><li><strong>No clang-format, clang-tidy or clangd programs</strong>: xclang is a compiler toolchain, and libclang has the libraries tools on clang link. They are <a href="./../design/roadmap#tool-binaries">not planned</a>.</li><li><strong>Not for building conda-forge packages</strong>: conda-forge&#39;s compilers link dynamically against packaged runtimes and integrate with <code>run_exports</code>; xclang does neither (<a href="./../design/roadmap#conda-forge">not planned</a>).</li></ul>',14)])])}const g=e(r,[["render",d]]);export{p as __pageData,g as default};
